package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Boolean;
    attribute lastHumidity : Real := 0.0;
    perform action tick {
      first start;
      then if io_1 {
        first start;
        then assign lastHumidity := io_0;
      }
    }
    out attribute serial_0_trigger : Boolean = io_1;
    out attribute serial_0_value_0 : Real = lastHumidity;
  }
  part system : Controller;
}
